def fourSumCount(arr, target):
    from collections import Counter
    from math import comb
    MOD = 1000000007
    cnt = Counter(arr)
    vals = sorted(cnt)
    m = len(vals)

    def ways(q):
        res = 1
        i = 0
        while i < 4:
            j = i
            while j < 4 and q[j] == q[i]:
                j += 1
            res *= comb(cnt[q[i]], j - i)
            if res == 0:
                return 0
            i = j
        return res

    total = 0
    for ia in range(m):
        for ib in range(ia, m):
            rest = target - vals[ia] - vals[ib]
            lo, hi = ib, m - 1
            while lo <= hi:
                s = vals[lo] + vals[hi]
                if s < rest:
                    lo += 1
                elif s > rest:
                    hi -= 1
                else:
                    total += ways((vals[ia], vals[ib], vals[lo], vals[hi]))
                    lo += 1
                    hi -= 1
    return total % MOD
